@font-face {
  font-family: "PF Din Text Cond Pro";
  src: url("data:font/truetype;charset=utf-8;base64,") format("truetype");
  font-weight: normal;
  font-style: normal;
}

@font-face {
  font-family: "PF Din Text Cond Pro";
  src: url("data:font/truetype;charset=utf-8;base64,") format("truetype");
  font-weight: bold;
  font-style: normal;
}

html, body {
  font-family: "PF Din Text Cond Pro", "PF DIN Text Pro", Arial, sans-serif !important;
  font-size: 14pt;
  line-height: 1.5;
}

body, p, div, span, table, thead, tbody, tr, th, td, li, ol, ul, strong, em, b, i {
  font-family: "PF Din Text Cond Pro", "PF DIN Text Pro", Arial, sans-serif !important;
}

p {
  font-size: 14pt;
  line-height: 1.5;
  text-align: justify;
  text-indent: 1.25cm;
}

ol, ul {
  font-size: 14pt;
  line-height: 1.5;
}

li {
  font-size: 14pt;
  line-height: 1.5;
  text-align: justify;
}

table {
  font-size: 12pt !important;
}

table th, table td {
  font-size: 12pt !important;
}

table th:first-child, table td:first-child {
  text-align: left !important;
}

table.acoustic-table, table.acoustic-table th, table.acoustic-table td {
  font-size: 10pt !important;
}
